//
// SwiftUI port of the desktop egui server selector + Android Compose
// selector. **Untested**: this file is built only on macOS (Swift Package
// Manager isn't available from the Linux dev box). When you next open
// Xcode, add this file to the Trireme target and confirm:
//
//   1. The bindings file `Trireme.swift` (generated by the Rust core's
//      uniffi-bindgen) exposes `clientPair(addr:pin:identityPath:ourAlias:)`
//      and `startVideoStream(addr:expectedPubkeyHex:sink:)`. If the symbols
//      have different camel-casing, adjust the call sites below.
//   2. The XCFramework script in `build-rust-ios.sh` was re-run so the new
//      symbols are present in the native lib.
//   3. `Info.plist` carries `NSLocalNetworkUsageDescription` if the user
//      will connect over LAN.

import SwiftUI

public struct ServerSelectorView: View {
    @StateObject private var model = ServerSelectorModel()

    public init() {}

    public var body: some View {
        NavigationStack {
            Group {
                if model.registry.servers.isEmpty {
                    emptyState
                } else {
                    grid
                }
            }
            .navigationTitle("Trireme")
            .toolbar {
                ToolbarItem(placement: .primaryAction) {
                    Button(action: { model.showAdd = true }) {
                        Label("Add server", systemImage: "plus")
                    }
                }
            }
            .safeAreaInset(edge: .bottom) {
                if !model.selected.isEmpty {
                    ConnectBar(
                        count: model.selected.count,
                        onConnect: model.connectSelected,
                        onClear: model.clearSelection
                    )
                }
            }
        }
        .sheet(isPresented: $model.showAdd) {
            EditSheet(
                title: "Add server",
                initialHost: "",
                initialPort: "15777",
                initialAlias: ""
            ) { host, port, alias in
                model.addOrUpdate(host: host, port: port, alias: alias, replacing: nil)
                model.showAdd = false
            }
        }
        .sheet(item: $model.editing) { target in
            EditSheet(
                title: "Edit server",
                initialHost: target.host,
                initialPort: String(target.port),
                initialAlias: target.alias ?? ""
            ) { host, port, alias in
                model.addOrUpdate(host: host, port: port, alias: alias, replacing: target.id)
                model.editing = nil
            }
        }
        .sheet(item: $model.pairing) { target in
            PairSheet(target: target) { pin, completion in
                model.runPair(target: target, pin: pin, completion: completion)
            }
        }
        .alert(item: $model.deleting) { target in
            Alert(
                title: Text("Delete server?"),
                message: Text("Forget '\(target.friendlyName())'?"),
                primaryButton: .destructive(Text("Delete")) {
                    model.delete(id: target.id)
                },
                secondaryButton: .cancel()
            )
        }
    }

    private var emptyState: some View {
        VStack(spacing: 8) {
            Text("No servers remembered yet.")
                .foregroundStyle(.secondary)
            Text("Tap + to add a Pharos host.")
                .foregroundStyle(.secondary)
                .font(.caption)
        }
    }

    private var grid: some View {
        ScrollView {
            LazyVGrid(
                columns: [GridItem(.adaptive(minimum: 200), spacing: 12)],
                spacing: 12
            ) {
                ForEach(model.registry.servers) { server in
                    ServerTile(
                        server: server,
                        checked: model.selected.contains(server.id),
                        multiSelectActive: !model.selected.isEmpty,
                        onTap: { model.tap(server) },
                        onLongPress: { model.toggleSelect(server.id) },
                        onEdit: { model.editing = server },
                        onDelete: { model.deleting = server },
                        onPair: { model.pairing = server }
                    )
                }
            }
            .padding(12)
        }
    }
}

// MARK: - Subviews

private struct ServerTile: View {
    let server: ServerEntry
    let checked: Bool
    let multiSelectActive: Bool
    let onTap: () -> Void
    let onLongPress: () -> Void
    let onEdit: () -> Void
    let onDelete: () -> Void
    let onPair: () -> Void

    var body: some View {
        VStack(alignment: .leading, spacing: 6) {
            HStack {
                Text(server.friendlyName()).font(.headline)
                Spacer()
                if multiSelectActive {
                    Image(systemName: checked ? "checkmark.circle.fill" : "circle")
                } else {
                    Menu {
                        Button(server.paired ? "Re-pair…" : "Pair…", action: onPair)
                        Button("Edit", action: onEdit)
                        Button("Delete", role: .destructive, action: onDelete)
                    } label: {
                        Image(systemName: "ellipsis")
                    }
                }
            }
            Text(server.addressLabel())
                .font(.caption)
                .foregroundStyle(.secondary)
            HStack(spacing: 8) {
                StatusBadge(
                    text: server.paired ? "Paired" : "Unpaired",
                    color: server.paired ? .green : .orange
                )
                if let pace = server.pace {
                    Text(pace).font(.caption).foregroundStyle(.secondary)
                }
            }
        }
        .padding(12)
        .background(.regularMaterial)
        .clipShape(RoundedRectangle(cornerRadius: 10))
        .contentShape(Rectangle())
        .onTapGesture(perform: onTap)
        .onLongPressGesture(perform: onLongPress)
    }
}

private struct StatusBadge: View {
    let text: String
    let color: Color
    var body: some View {
        Text(text)
            .font(.caption2)
            .padding(.horizontal, 6)
            .padding(.vertical, 2)
            .background(color.opacity(0.18))
            .foregroundStyle(color)
            .clipShape(RoundedRectangle(cornerRadius: 4))
    }
}

private struct ConnectBar: View {
    let count: Int
    let onConnect: () -> Void
    let onClear: () -> Void
    var body: some View {
        HStack {
            Button("Clear", action: onClear)
            Spacer()
            Button(count == 1 ? "Connect" : "Connect (\(count))", action: onConnect)
                .buttonStyle(.borderedProminent)
        }
        .padding()
        .background(.regularMaterial)
    }
}

private struct EditSheet: View {
    let title: String
    let initialHost: String
    let initialPort: String
    let initialAlias: String
    let onCommit: (String, Int, String) -> Void

    @State private var host: String = ""
    @State private var port: String = ""
    @State private var alias: String = ""
    @Environment(\.dismiss) private var dismiss

    var body: some View {
        NavigationStack {
            Form {
                Section {
                    TextField("Host", text: $host)
                        .autocorrectionDisabled()
                        .textInputAutocapitalization(.never)
                    TextField("Port", text: $port)
                        .keyboardType(.numberPad)
                    TextField("Alias (optional)", text: $alias)
                }
            }
            .navigationTitle(title)
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Cancel") { dismiss() }
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button("Save") {
                        if let p = Int(port.trimmingCharacters(in: .whitespaces)),
                           !host.trimmingCharacters(in: .whitespaces).isEmpty {
                            onCommit(host.trimmingCharacters(in: .whitespaces), p, alias)
                        }
                    }
                    .disabled(!isValid)
                }
            }
            .onAppear {
                host = initialHost
                port = initialPort
                alias = initialAlias
            }
        }
    }

    private var isValid: Bool {
        !host.trimmingCharacters(in: .whitespaces).isEmpty &&
        (Int(port) ?? 0) > 0 && (Int(port) ?? 0) <= 65535
    }
}

private struct PairSheet: View {
    let target: ServerEntry
    let onPair: (String, @escaping (Result<String, Error>) -> Void) -> Void

    @State private var pin: String = ""
    @State private var inFlight = false
    @State private var result: Result<String, Error>?
    @Environment(\.dismiss) private var dismiss

    var body: some View {
        NavigationStack {
            Form {
                Section(footer: Text("Run `pharos-compositor pair` on the host to see the PIN.")) {
                    SecureField("PIN (6 digits)", text: $pin)
                        .keyboardType(.numberPad)
                }
                if inFlight {
                    HStack {
                        ProgressView()
                        Text("Running SPAKE2 handshake…")
                    }
                }
                if case .success(let pub)? = result {
                    Text("Paired ✓ — \(String(pub.prefix(8)))…").foregroundStyle(.green)
                }
                if case .failure(let err)? = result {
                    Text("Failed: \(err.localizedDescription)").foregroundStyle(.red)
                }
            }
            .navigationTitle("Pair with \(target.friendlyName())")
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Cancel") { dismiss() }.disabled(inFlight)
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button("Start") {
                        inFlight = true
                        result = nil
                        onPair(pin) { r in
                            inFlight = false
                            result = r
                        }
                    }
                    .disabled(inFlight || pin.count != 6 || !pin.allSatisfy(\.isNumber))
                }
            }
        }
    }
}
